# collect every SKILL.md across all installed plugins (cache) and loose ~/.claude/skills, record (name -> source path)
python3 << 'EOF'
import os, hashlib, json
from collections import defaultdict

roots = []
# plugin cache
plugin_cache = os.path.expanduser("~/.claude/plugins/cache")
for marketplace in os.listdir(plugin_cache):
    mdir = os.path.join(plugin_cache, marketplace)
    if not os.path.isdir(mdir): continue
    for plugin in os.listdir(mdir):
        pdir = os.path.join(mdir, plugin)
        if not os.path.isdir(pdir): continue
        for version in os.listdir(pdir):
            vdir = os.path.join(pdir, version)
            if not os.path.isdir(vdir): continue
            for dirpath, dirnames, filenames in os.walk(vdir):
                if 'node_modules' in dirpath or '.git' in dirpath: continue
                if 'SKILL.md' in filenames:
                    skillname = os.path.basename(dirpath)
                    roots.append((f"plugin:{marketplace}/{plugin}@{version}", skillname, os.path.join(dirpath, "SKILL.md")))

# loose skills
loose_dir = os.path.expanduser("~/.claude/skills")
for name in os.listdir(loose_dir):
    p = os.path.join(loose_dir, name)
    real = os.path.realpath(p)
    skillmd = os.path.join(real, "SKILL.md")
    if os.path.isfile(skillmd):
        roots.append(("loose:~/.claude/skills", name, skillmd))
    else:
        # might be a dir with nested skill.md directly (non-symlink case)
        for dirpath, dirnames, filenames in os.walk(real):
            if 'SKILL.md' in filenames:
                roots.append(("loose:~/.claude/skills", os.path.basename(dirpath), os.path.join(dirpath, "SKILL.md")))

byname = defaultdict(list)
for source, name, path in roots:
    byname[name].append((source, path))

def h(path):
    try:
        return hashlib.sha256(open(path,'rb').read()).hexdigest()[:12]
    except Exception as e:
        return f"ERR:{e}"

print(f"Total skill entries scanned: {len(roots)}")
print(f"Unique skill names: {len(byname)}\n")
print("=== NAME COLLISIONS (same skill-folder-name from 2+ sources) ===")
for name, entries in sorted(byname.items()):
    if len(entries) > 1:
        hashes = set(h(p) for _, p in entries)
        status = "IDENTICAL" if len(hashes) == 1 else "DIFFERS"
        print(f"\n[{status}] {name}  ({len(entries)} sources)")
        for source, path in entries:
            print(f"    {source}  ->  {path}")
EOF

